estilos.css:
.app-header {
  min-height: 64px;
  display: grid;
  grid-template-columns: 42px minmax(0,1fr) 42px;
  gap: 10px;
  align-items: center;
  padding: 8px 14px;
  background: var(--primary);
  color: #fff;
  box-shadow: 0 4px 14px rgba(16,35,63,.18);
}
.app-menu-button,
.app-notifications {
  width: 40px;
  height: 40px;
  display: grid;
  place-content: center;
  border: 0;
  border-radius: 10px;
  background: transparent;
  color: #fff;
  cursor: pointer;
}
.app-menu-button { gap: 4px; }
.app-menu-button span {
  width: 20px;
  height: 2px;
  border-radius: 9px;
  background: currentColor;
}
.app-brand {
  min-width: 0;
  display: flex;
  align-items: center;
  gap: 9px;
}
.app-brand img {
  width: 28px;
  height: 28px;
  object-fit: contain;
  filter: brightness(0) invert(1);
}
.app-brand-copy { min-width: 0; }
.app-brand-copy strong,
.app-brand-copy small { display:block; }
.app-brand-copy strong {
  overflow:hidden;
  text-overflow:ellipsis;
  white-space:nowrap;
  font-size:16px;
  letter-spacing:-.02em;
}
.app-brand-copy small {
  margin-top:1px;
  font-size:9px;
  font-weight:800;
  letter-spacing:.08em;
  text-transform:uppercase;
  opacity:.72;
}
.app-notifications {
  position: relative;
  justify-self: end;
}
.app-notifications svg {
  width: 22px;
  height: 22px;
  fill: none;
  stroke: currentColor;
  stroke-width: 1.7;
  stroke-linecap: round;
  stroke-linejoin: round;
}
.app-notifications-badge {
  position:absolute;
  top:4px;
  right:2px;
  min-width:16px;
  height:16px;
  padding:0 4px;
  display:grid;
  place-items:center;
  border:2px solid var(--primary);
  border-radius:999px;
  background:#ef4444;
  color:#fff;
  font-size:9px;
  font-weight:800;
}

.home-intro {
  padding: 2px 2px 4px;
}
.home-eyebrow {
  display:block;
  margin-bottom:6px;
  color:var(--gold);
  font-size:11px;
  font-weight:900;
  letter-spacing:.08em;
  text-transform:uppercase;
}
.home-intro h1 {
  margin:0;
  color:var(--primary);
  font-size:24px;
  line-height:1.15;
  letter-spacing:-.025em;
}
.home-intro p {
  max-width:560px;
  margin:8px 0 0;
  color:var(--muted);
  font-size:14px;
  line-height:1.5;
}

.online-card {
  width:100%;
  display:grid;
  grid-template-columns:auto minmax(0,1fr) auto;
  gap:12px;
  align-items:center;
  padding:14px 15px;
  border:1px solid #a8dfc8;
  border-radius:16px;
  background:#f1fbf6;
  color:var(--text);
  text-align:left;
  cursor:pointer;
}
.online-card.is-offline {
  border-color:var(--line);
  background:#f8fafc;
}
.online-dot {
  width:10px;
  height:10px;
  border-radius:50%;
  background:#15945e;
  box-shadow:0 0 0 4px rgba(21,148,94,.12);
}
.is-offline .online-dot {
  background:#98a2b3;
  box-shadow:none;
}
.online-copy strong,
.online-copy small { display:block; }
.online-copy strong {
  color:var(--primary);
  font-size:14px;
}
.online-copy small {
  margin-top:3px;
  color:var(--muted);
  font-size:12px;
}
.online-switch {
  position:relative;
  width:40px;
  height:23px;
  border-radius:999px;
  background:#22c55e;
}
.online-switch b {
  position:absolute;
  top:3px;
  right:3px;
  width:17px;
  height:17px;
  border-radius:50%;
  background:#fff;
}
.is-offline .online-switch { background:#98a2b3; }
.is-offline .online-switch b { right:20px; }

.requests-block { display:grid; gap:12px; }
.requests-heading {
  display:flex;
  justify-content:space-between;
  gap:12px;
  align-items:end;
}
.requests-heading h2 {
  margin:0;
  color:var(--primary);
  font-size:18px;
  letter-spacing:-.015em;
}
.requests-heading p {
  margin:4px 0 0;
  color:var(--muted);
  font-size:12px;
}
.requests-list { display:grid; gap:10px; }
.request-card {
  width:100%;
  display:block;
  padding:15px;
  border:1px solid var(--line);
  border-radius:16px;
  background:#fff;
  color:var(--text);
  text-align:left;
  cursor:pointer;
  box-shadow:0 2px 7px rgba(16,35,63,.035);
}
.request-card:hover { border-color:#bac7d8; }
.request-top {
  display:flex;
  justify-content:space-between;
  gap:10px;
  align-items:center;
}
.request-priority {
  display:inline-flex;
  align-items:center;
  min-height:24px;
  padding:3px 9px;
  border-radius:999px;
  background:#fff7e8;
  color:#8a5a08;
  font-size:10px;
  font-weight:900;
  text-transform:uppercase;
  letter-spacing:.045em;
}
.request-time {
  color:var(--muted);
  font-size:11px;
}
.request-card h3 {
  margin:12px 0 0;
  color:var(--primary);
  font-size:16px;
}
.request-meta {
  margin:5px 0 0;
  color:var(--muted);
  font-size:12px;
  line-height:1.45;
}
.request-summary {
  margin:11px 0 0;
  color:#344054;
  font-size:13px;
  line-height:1.5;
}
.request-open {
  margin-top:13px;
  display:flex;
  justify-content:flex-end;
  gap:6px;
  align-items:center;
  color:var(--primary-soft);
  font-size:12px;
  font-weight:800;
}
.request-open b {
  color:var(--gold);
  font-size:20px;
  line-height:1;
}
@media(min-width:680px) {
  .requests-list { grid-template-columns:1fr 1fr; }
  .request-card:first-child { grid-column:1 / -1; }
}

.prototype-drawer {
  position: fixed;
  z-index: 40;
  inset: 0;
  display: none;
}

.prototype-drawer.open { display: block; }

.drawer-backdrop {
  position: absolute;
  inset: 0;
  width: 100%;
  border: 0;
  background: rgba(7, 16, 30, .60);
}

.drawer-panel {
  position: absolute;
  inset: 0 auto 0 0;
  width: min(80vw, 360px);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  background: #3b4a7d;
  color: #fff;
  box-shadow: 12px 0 30px rgba(0, 0, 0, .32);
}

.drawer-top {
  flex: 0 0 auto;
  min-height: 106px;
  padding: 30px 22px 20px;
  display: flex;
  align-items: center;
}

.drawer-identity {
  min-width: 0;
  display: flex;
  gap: 14px;
  align-items: center;
}

.drawer-avatar {
  flex: 0 0 56px;
  width: 56px;
  height: 56px;
  display: grid;
  place-items: center;
  border: 2px solid rgba(255, 255, 255, .20);
  border-radius: 50%;
  background: #dbeafe;
  color: #1e3a8a;
  font-size: 20px;
  font-weight: 800;
}

.drawer-profile { min-width: 0; }
.drawer-profile strong,
.drawer-profile small { display: block; }
.drawer-profile strong {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 16px;
  font-weight: 600;
}
.drawer-profile small {
  margin-top: 2px;
  color: #bfdbfe;
  font-size: 11px;
  font-weight: 400;
  text-transform: lowercase;
}

.drawer-online {
  flex: 0 0 auto;
  width: calc(100% - 44px);
  margin: 0 22px 10px;
  display: grid;
  grid-template-columns: auto 1fr auto;
  gap: 10px;
  align-items: center;
  border: 1px solid rgba(255, 255, 255, .18);
  border-radius: 10px;
  padding: 10px 12px;
  background: rgba(255, 255, 255, .08);
  color: #fff;
  text-align: left;
  cursor: pointer;
}
.drawer-online-copy strong,
.drawer-online-copy small { display: block; }
.drawer-online-copy strong { font-size: 13px; }
.drawer-online-copy small { margin-top: 2px; color: #bfdbfe; font-size: 10px; }
.online-dot {
  width: 9px;
  height: 9px;
  border-radius: 50%;
  background: #4ade80;
  box-shadow: 0 0 0 4px rgba(74, 222, 128, .14);
}
.drawer-online.is-offline .online-dot { background: #98a2b3; box-shadow: none; }
.online-switch { position: relative; width: 38px; height: 22px; border-radius: 999px; background: #22c55e; }
.online-switch b { position: absolute; top: 3px; right: 3px; width: 16px; height: 16px; border-radius: 50%; background: #fff; }
.drawer-online.is-offline .online-switch { background: #64748b; }
.drawer-online.is-offline .online-switch b { right: 19px; }

.drawer-nav {
  flex: 1 1 auto;
  min-height: 0;
  display: block;
  margin: 0;
  padding: 0 0 8px;
  overflow-x: hidden;
  overflow-y: auto;
  overscroll-behavior: contain;
  -webkit-overflow-scrolling: touch;
  scrollbar-width: thin;
  scrollbar-color: rgba(255, 255, 255, .35) transparent;
}
.drawer-nav::-webkit-scrollbar { width: 5px; }
.drawer-nav::-webkit-scrollbar-thumb { border-radius: 999px; background: rgba(255, 255, 255, .35); }

.drawer-nav button {
  width: 100%;
  min-height: 51px;
  padding: 14px 22px;
  border: 0;
  border-bottom: 1px solid rgba(255, 255, 255, .10);
  background: transparent;
  color: #f8fafc;
  display: flex;
  gap: 15px;
  align-items: center;
  text-align: left;
  font-size: 14px;
  font-weight: 400;
  cursor: pointer;
}
.drawer-nav button:hover { background: rgba(255, 255, 255, .08); }
.drawer-icon { flex: 0 0 20px; width: 20px; height: 20px; color: #aebee5; }

.drawer-footer {
  flex: 0 0 auto;
  margin-top: 0;
  padding: 16px 22px 30px;
  display: flex;
  flex-direction: column;
  gap: 22px;
  background: rgba(0, 0, 0, .10);
}
.drawer-footer-top { display: flex; justify-content: space-between; gap: 12px; align-items: center; }
.drawer-logout {
  min-height: 32px;
  padding: 0;
  border: 0;
  background: transparent;
  color: #f8fafc;
  display: flex;
  gap: 10px;
  align-items: center;
  font-size: 14px;
  cursor: pointer;
}
.drawer-logout svg { width: 18px; height: 18px; color: #aebee5; }
.drawer-footer small { color: #aebee5; font-size: 10px; }
.drawer-emergency {
  min-height: 41px;
  border: 1px solid rgba(255, 255, 255, .54);
  border-radius: 999px;
  background: transparent;
  color: #fff;
  font-size: 14px;
  font-weight: 600;
  cursor: pointer;
}
.drawer-emergency:hover { background: rgba(255, 255, 255, .08); }

@media (max-width: 420px) {
  .drawer-panel { width: 80vw; }
  .drawer-top { padding-top: 24px; }
}

